+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { Skeleton } from "@/components/ui/skeleton";
+import { useQuery } from "@tanstack/react-query";
+import { api } from "@/lib/api";
+import type { AgreementStatus } from "@/types/api";
+
+interface AgreementStats {
+  active: number;
+  byStatus: Record<AgreementStatus, number>;
+}
+
+export function ActiveAgreements() {
+  const { data: agreements, isLoading } = useQuery({
+    queryKey: ["agreements"],
+    queryFn: () => api.listAgreements({ page: 1, page_size: 1000 }),
+  });
+
+  const stats: AgreementStats = {
+    active: agreements?.items?.filter((a) => a.status === "active")?.length || 0,
+    byStatus: (agreements?.items ?? []).reduce((acc, item) => {
+      acc[item.status] = (acc[item.status] || 0) + 1;
+      return acc;
+    }, {} as Record<AgreementStatus, number>),
+  };
+
+  return (
+    <Card>
+      <CardHeader>
+        <CardTitle>Active Agreements</CardTitle>
+      </CardHeader>
+      <CardContent>
+        {isLoading ? (
+          <Skeleton className="h-20 w-full" />
+        ) : (
+          <div className="space-y-4">
+            <div className="text-center">
+              <span className="text-3xl font-bold text-emerald-400">{stats.active}</span>
+              <p className="text-sm text-slate-500 mt-1">Active Agreements</p>
+            </div>
+            <div className="pt-4 border-t border-slate-700">
+              <p className="text-xs font-medium text-slate-400 mb-2">Status Breakdown</p>
+              {Object.entries(stats.byStatus).map(([status, count]) => (
+                <div key={status} className="flex items-center justify-between py-1">
+                  <span className="text-xs text-slate-300 capitalize">{status}</span>
+                  <span className="text-xs font-medium">{count}</span>
+                </div>
+              ))}
+            </div>
+          </div>
+        )}
+      </CardContent>
+    </Card>
+  );
+}

