+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { Skeleton } from "@/components/ui/skeleton";
+import { useQuery } from "@tanstack/react-query";
+import { api } from "@/lib/api";
+
+interface SustainabilityTotals {
+  energySaved: number;
+  co2Avoided: number;
+}
+
+function formatNumber(value: number): string {
+  if (value >= 1000000) {
+    return (value / 1000000).toFixed(2) + "M";
+  } else if (value >= 1000) {
+    return (value / 1000).toFixed(2) + "k";
+  }
+  return value.toFixed(2);
+}
+
+export function SustainabilityTotals() {
+  const { data: sustainabilityRecords, isLoading } = useQuery({
+    queryKey: ["sustainability"],
+    queryFn: () => api.listSustainability({ page: 1, page_size: 1000 }),
+  });
+
+  const totals = sustainabilityRecords?.items.reduce((acc, record) => ({
+    energySaved: acc.energySaved + (record.total_energy_saved_kwh || 0),
+    co2Avoided: acc.co2Avoided + (record.co2_emissions_avoided_tco2e || 0)
+  }), { energySaved: 0, co2Avoided: 0 }) || { energySaved: 0, co2Avoided: 0 };
+
+  return (
+    <Card>
+      <CardHeader>
+        <CardTitle>Sustainability Totals</CardTitle>
+      </CardHeader>
+      <CardContent>
+        {isLoading ? (
+          <Skeleton className="h-20 w-full" />
+        ) : (
+          <div className="space-y-4">
+            <div className="text-center">
+              <span className="text-3xl font-bold text-green-400">{formatNumber(totals.energySaved)}</span>
+              <p className="text-sm text-slate-500 mt-1">Energy Saved (kWh)</p>
+            </div>
+            <div className="text-center">
+              <span className="text-3xl font-bold text-emerald-400">{formatNumber(totals.co2Avoided)}</span>
+              <p className="text-sm text-slate-500 mt-1">CO₂ Avoided (tCO₂e)</p>
+            </div>
+          </div>
+        )}
+      </CardContent>
+    </Card>
+  );
+}

