+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { Skeleton } from "@/components/ui/skeleton";
+import { useQuery } from "@tanstack/react-query";
+import { api } from "@/lib/api";
+
+interface TimeStats {
+  total: number;
+  billable: number;
+}
+
+function formatHours(hours: number): string {
+  return hours.toFixed(1);
+}
+
+export function TimeLoggedThisMonth() {
+  const { data: timeLogs, isLoading } = useQuery({
+    queryKey: ["timeLogs"],
+    queryFn: () => api.listTimeLogs({ page: 1, page_size: 1000 }),
+  });
+
+  const filteredLogs = timeLogs?.items || [];
+
+  const stats: TimeStats = {
+    total: filteredLogs.reduce((sum, log) => sum + (log.hours_logged || 0), 0),
+    billable: filteredLogs.reduce((sum, log) => sum + (log.billable_hours || 0), 0),
+  };
+
+  const billablePercentage = stats.total > 0 ? (stats.billable / stats.total) * 100 : 0;
+
+  return (
+    <Card>
+      <CardHeader>
+        <CardTitle>Time Logged This Month</CardTitle>
+      </CardHeader>
+      <CardContent>
+        {isLoading ? (
+          <Skeleton className="h-20 w-full" />
+        ) : (
+          <div className="space-y-4">
+            <div className="text-center">
+              <span className="text-3xl font-bold text-blue-400">{formatHours(stats.total)}</span>
+              <p className="text-sm text-slate-500 mt-1">Total Hours</p>
+            </div>
+            <div className="text-center">
+              <span className="text-3xl font-bold text-emerald-400">{formatHours(stats.billable)}</span>
+              <p className="text-sm text-slate-500 mt-1">Billable Hours</p>
+            </div>
+            <div className="pt-2">
+              <div className="flex items-center justify-between mb-1">
+                <span className="text-xs text-slate-400">Billable %</span>
+                <span className="text-xs font-medium">{billablePercentage.toFixed(1)}%</span>
+              </div>
+              <div className="w-full bg-slate-700 rounded-full h-2">
+                <div 
+                  className="bg-emerald-400 h-2 rounded-full" 
+                  style={{ width: `${billablePercentage}%` }}
+                />
+              </div>
+            </div>
+          </div>
+        )}
+      </CardContent>
+    </Card>
+  );
+}

