import { useDashboard } from "@/hooks/useDashboard";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { IndianRupee, FolderOpen, FileText, Hammer, TrendingUp } from "lucide-react";

function formatINR(value: number): string {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(value);
}

const gradients = [
  "from-blue-500/10 to-blue-600/5 border-blue-500/20",
  "from-emerald-500/10 to-emerald-600/5 border-emerald-500/20",
  "from-amber-500/10 to-amber-600/5 border-amber-500/20",
  "from-rose-500/10 to-rose-600/5 border-rose-500/20",
];

const iconColors = [
  "text-blue-400",
  "text-emerald-400",
  "text-amber-400",
  "text-rose-400",
];

export function StatsCards() {
  const { data: stats, isLoading } = useDashboard();

  const cards = [
    {
      title: "Active Projects",
      value: stats?.total_active ?? 0,
      icon: FolderOpen,
      format: (v: number) => v.toString(),
      subtitle: "Across all clients",
      trend: "+12%",
    },
    {
      title: "Pipeline Value",
      value: stats?.total_estimated_value ?? 0,
      icon: IndianRupee,
      format: formatINR,
      subtitle: "Total estimated",
      trend: "+8%",
    },
    {
      title: "In Quote Stage",
      value: stats?.by_status?.Quote ?? 0,
      icon: FileText,
      format: (v: number) => v.toString(),
      subtitle: "Awaiting approval",
      trend: "+3",
    },
    {
      title: "In Execution",
      value: stats?.by_status?.Execution ?? 0,
      icon: Hammer,
      format: (v: number) => v.toString(),
      subtitle: "Active on site",
      trend: "+2",
    },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
      {cards.map((card, i) => (
        <Card
          key={card.title}
          className={`relative overflow-hidden bg-gradient-to-br ${gradients[i]} border ${i === 0 ? '' : ''}`}
        >
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-slate-300">{card.title}</CardTitle>
            <card.icon className={`h-4 w-4 ${iconColors[i]}`} />
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <Skeleton className="h-8 w-20" />
            ) : (
              <div className="text-2xl font-bold text-white">{card.format(card.value)}</div>
            )}
            <div className="mt-1 flex items-center justify-between">
              <p className="text-xs text-slate-500">{card.subtitle}</p>
              <span className="flex items-center gap-0.5 text-xs font-medium text-emerald-400">
                <TrendingUp className="h-3 w-3" />
                {card.trend}
              </span>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

