import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import type { InquiryStatus, Token } from "@/types/api";

interface InquiryStats {
  open: number;
  converted: number;
}

export function InquiriesByStatus() {
  const { data: inquiries, isLoading } = useQuery({
    queryKey: ["inquiries"],
    queryFn: () => api.listInquiries({ page: 1, page_size: 1000 }),
  });

  const stats: InquiryStats = {
    open: inquiries?.items.filter((i) => i.status === "open").length || 0,
    converted: inquiries?.items.filter((i) => i.status === "converted").length || 0,
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Inquiries by Status</CardTitle>
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <Skeleton className="h-20 w-full" />
        ) : (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-sm text-slate-300">Open</span>
              <span className="text-2xl font-bold text-blue-400">{stats.open}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-slate-300">Converted</span>
              <span className="text-2xl font-bold text-emerald-400">{stats.converted}</span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import type { AgreementStatus, ServiceAgreement } from "@/types/api";

interface AgreementStats {
  active: number;
  byStatus: Record<AgreementStatus, number>;
}

export function ActiveAgreements() {
  const { data: agreements, isLoading } = useQuery({
    queryKey: ["agreements"],
    queryFn: () => api.listAgreements({ page: 1, page_size: 1000 }),
  });

  const stats: AgreementStats = {
    active: agreements?.items.filter((a) => a.status === "active").length || 0,
    byStatus: agreements?.items.reduce((acc, item) => {
      acc[item.status] = (acc[item.status] || 0) + 1;
      return acc;
    }, {} as Record<AgreementStatus, number>) || {},
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Active Agreements</CardTitle>
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <Skeleton className="h-20 w-full" />
        ) : (
          <div className="space-y-4">
            <div className="text-center">
              <span className="text-3xl font-bold text-emerald-400">{stats.active}</span>
              <p className="text-sm text-slate-500 mt-1">Active Agreements</p>
            </div>
            <div className="pt-4 border-t border-slate-700">
              <p className="text-xs font-medium text-slate-400 mb-2">Status Breakdown</p>
              {Object.entries(stats.byStatus).map(([status, count]) => (
                <div key={status} className="flex items-center justify-between py-1">
                  <span className="text-xs text-slate-300 capitalize">{status}</span>
                  <span className="text-xs font-medium">{count}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

