}

export function InquiriesByStatus() {
  const { data: inquiries, isLoading } = useQuery({
    queryKey: ["inquiries"],
    queryFn: () => api.listInquiries({ page: 1, page_size: 1000 }),
  });

  const stats: InquiryStats = {
    open: inquiries?.items.filter((i) => i.status === "open").length || 0,
