import { Skeleton } from "@/components/ui/skeleton";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import type { ProjectStatus, Project } from "@/types/api";

interface ProjectStatusStats {
  byStatus: Record<ProjectStatus, number>;
}

export function ProjectsByMilestone() {
  const { data: projects, isLoading } = useQuery({
    queryKey: ["projects"],
    queryFn: () => api.listProjects({ page: 1, page_size: 1000 }),
  });

  const stats: ProjectStatusStats = {
    byStatus: projects?.items.reduce((acc, item) => {
      acc[item.status] = (acc[item.status] || 0) + 1;
      return acc;
    }, {} as Record<ProjectStatus, number>),
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Projects by Milestone</CardTitle>
      </CardHeader>
