              <div key={status} className="flex items-center justify-between">
                <span className="text-sm text-slate-300 capitalize">{status}</span>
                <span className="text-lg font-bold text-white">{count}</span>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

